'''
import pandas as pd

df = pd.read_csv("support_queue.csv")

# Identify likely columns
cols = {c.lower(): c for c in df.columns}
team_col = None
resolved_col = None

for key in cols:
    if key in {"team", "assignee_team", "support_team", "queue_team"}:
        team_col = cols[key]
    if key in {"resolved", "is_resolved", "status"}:
        resolved_col = cols[key]

if team_col is None:
    # fallback: first column containing team
    for c in df.columns:
        if "team" in c.lower():
            team_col = c
            break

if resolved_col is None:
    # fallback: first column containing resolved/status
    for c in df.columns:
        if "resolved" in c.lower() or "status" in c.lower():
            resolved_col = c
            break

if team_col is None or resolved_col is None:
    raise ValueError(f"Could not identify team/resolved columns. Columns: {list(df.columns)}")

# Count resolved tickets per team
resolved_values = df[resolved_col]

# Handle both boolean/flag and status strings
if resolved_values.dtype == bool:
    resolved_mask = resolved_values
else:
    resolved_mask = resolved_values.astype(str).str.lower().isin(["resolved", "true", "1", "yes", "y"])

counts = df.loc[resolved_mask].groupby(team_col).size().sort_values(ascending=False)

top_team = counts.index[0]
top_count = int(counts.iloc[0])

print(f"Top team: {top_team}")
print(f"Resolved count: {top_count}")
''')

